shell_commands:
cat << 'EOF' >> src/transport/ws/validation.test.ts

  it('accepts list_sessions with valid or absent limit and before, dropping unknown fields', () => {
    expect(validateMessage({type: 'list_sessions', unknown: 'drop'})).toEqual({
      valid: true,
      data: {type: 'list_sessions'},
    });
    expect(validateMessage({type: 'list_sessions', limit: 10})).toEqual({
      valid: true,
      data: {type: 'list_sessions', limit: 10},
    });
    expect(
      validateMessage({
        type: 'list_sessions',
        limit: 100,
        before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's1'},
      })
    ).toEqual({
      valid: true,
      data: {
        type: 'list_sessions',
        limit: 100,
        before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's1'},
      },
    });
    expect(
      validateMessage({
        type: 'list_sessions',
        limit: 100,
        before: {updatedAt: 123456789, sessionId: 's1'},
      })
    ).toEqual({
      valid: true,
      data: {
        type: 'list_sessions',
        limit: 100,
        before: {updatedAt: 123456789, sessionId: 's1'},
      },
    });
  });

  it('rejects list_sessions with invalid limit or before', () => {
    expect(validateMessage({type: 'list_sessions', limit: '10'})).toEqual({
      valid: false,
      error: expect.stringMatching(/limit/i),
    });
    expect(validateMessage({type: 'list_sessions', limit: 1.5})).toEqual({
      valid: false,
      error: expect.stringMatching(/limit/i),
    });
    expect(validateMessage({type: 'list_sessions', limit: -1})).toEqual({
      valid: false,
      error: expect.stringMatching(/limit/i),
    });
    expect(validateMessage({type: 'list_sessions', before: 'not-an-object'})).toEqual({
      valid: false,
      error: expect.stringMatching(/before/i),
    });
    expect(validateMessage({type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: ''}})).toEqual({
      valid: false,
      error: expect.stringMatching(/sessionId/i),
    });
    expect(validateMessage({type: 'list_sessions', before: {updatedAt: 'not-a-date', sessionId: 's1'}})).toEqual({
      valid: false,
      error: expect.stringMatching(/updatedAt/i),
    });
  });
EOF
